export function alpha(n) {
  // realistic body: compute a checksum-ish value over a derived sequence
  let acc = 17;
  const parts = [];
  for (let i = 0; i < n + 4; i++) {
    const v = (i * 31 + 7) % 97;
    parts.push(v);
    acc = (acc * 33 + v) % 1000003;
  }
  const tag = parts.map((p) => p.toString(16)).join('-');
  return { kind: 'alpha', acc, tag, count: parts.length };
}

export function beta(n) {
  // realistic body: build a small table and fold it into a summary string
  const rows = [];
  let total = 0;
  for (let i = 1; i <= n + 2; i++) {
    const w = i * i + 3 * i + 1;
    total += w;
    rows.push({ i, w, running: total });
  }
  const summary = rows.map((r) => `${r.i}:${r.w}:${r.running}`).join('|');
  return { kind: 'beta', total, summary, rows: rows.length };
}
